    drawings:r.drawings.map(d=>({mapId:d.mapId,kind:d.kind,color:d.color,width:d.kind==='line'?(d.width??3):null,icon:d.kind==='note'?(d.icon||'number'):null,text:d.text||'',points:d.points})),excluded:r.excluded,
